#include "unity.h"
#include "header.h"
#include "helpers.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void setUp(void) { }
void tearDown(void) { }

void unit_test_print_number_negative_num_digits_all_nonzero(void) {
    uint8_t N = 5;
    uint8_t number[] = {3, 2, 1, 0, 0};  // Little-endian: represents "00123" -> "123"
    int8_t num_digits_to_print = -1;  // Negative means print all non-zero digits

    char buffer[256];
    FILE *old_stdout = stdout;
    stdout = fmemopen(buffer, sizeof(buffer), "w");
    if (stdout == NULL) {
        TEST_FAIL_MESSAGE("fmemopen failed");
        return;
    }
    setbuf(stdout, NULL);
    int result = print_number(number, N, num_digits_to_print);
    fflush(stdout);
    fclose(stdout);
    stdout = old_stdout;
    char *output = strdup(buffer);

    TEST_ASSERT_EQUAL_INT(0, result);
    TEST_ASSERT_EQUAL_STRING("123
", output);

    free(output);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_print_number_negative_num_digits_all_nonzero);
    return UNITY_END();
}

